const assert = require('assert');

class LoanAccount {
    constructor(loanId) {
        this.loanId = loanId;
        this.feesDue = 0;
        this.interestDue = 0;
        this.principalDue = 0;
        this.unapplied = 0;
        this.auditLog = [];
        this._idempotencyKeys = new Set();
    }

    addCharges(fees, interest, principal) {
        this.feesDue += fees;
        this.interestDue += interest;
        this.principalDue += principal;
    }

    // applyPayment(paymentId, amount):
    // 1. Idempotent: if paymentId already seen, return the cached result (no side effects)
    // 2. Waterfall order: fees → interest → principal → unapplied
    //    Each bucket gets min(remaining, bucketDue), reducing both remaining and bucketDue
    // 3. Any leftover goes to this.unapplied
    // 4. Push audit entry: { paymentId, applied: { fees, interest, principal, unapplied } }
    // 5. Cache and return the applied object

golden_completion:
applyPayment(paymentId, amount) {
    if (this._idempotencyKeys.has(paymentId)) {
        return this.auditLog.find(e => e.paymentId === paymentId).applied;
    }
    this._idempotencyKeys.add(paymentId);
    let remaining = amount;
    const feePart = Math.min(remaining, this.feesDue);
    this.feesDue -= feePart;
    remaining -= feePart;
    const intPart = Math.min(remaining, this.interestDue);
    this.interestDue -= intPart;
    remaining -= intPart;
    const prinPart = Math.min(remaining, this.principalDue);
    this.principalDue -= prinPart;
    remaining -= prinPart;
    this.unapplied += remaining;
    const applied = { fees: feePart, interest: intPart, principal: prinPart, unapplied: remaining };
    this.auditLog.push({ paymentId, applied });
    return applied;
}

suffix:
}

const loan = new LoanAccount('L1');
loan.addCharges(50, 200, 1000);
const r1 = loan.applyPayment('P1', 300);
assert.deepStrictEqual(r1, { fees: 50, interest: 200, principal: 50, unapplied: 0 });
assert.strictEqual(loan.feesDue, 0);
assert.strictEqual(loan.interestDue, 0);
assert.strictEqual(loan.principalDue, 950);

assertions:
// Idempotency: same paymentId returns cached result, no side effects
const r1dup = loan.applyPayment('P1', 300);
assert.deepStrictEqual(r1dup, { fees: 50, interest: 200, principal: 50, unapplied: 0 });
assert.strictEqual(loan.principalDue, 950);  // unchanged

// Second payment: all goes to principal since fees/interest are zero
const r2 = loan.applyPayment('P2', 500);
assert.deepStrictEqual(r2, { fees: 0, interest: 0, principal: 500, unapplied: 0 });
assert.strictEqual(loan.principalDue, 450);

// Overpayment: excess to unapplied
const r3 = loan.applyPayment('P3', 600);
assert.deepStrictEqual(r3, { fees: 0, interest: 0, principal: 450, unapplied: 150 });
assert.strictEqual(loan.principalDue, 0);
assert.strictEqual(loan.unapplied, 150);
assert.strictEqual(loan.auditLog.length, 3);

