pick(pickId, sku, requestedQty, currentDate) {
        if (this.picks[pickId]) return this.picks[pickId];

        const eligible = this.batches
            .filter(b => b.sku === sku && b.qty > 0 && b.expiry > currentDate)
            .sort((a, b) => a.expiry.localeCompare(b.expiry));

        const totalAvailable = eligible.reduce((sum, b) => sum + b.qty, 0);
        let remaining = requestedQty;
        const items = [];
        const deducted = [];

        for (const batch of eligible) {
            if (remaining <= 0) break;
            const taken = Math.min(batch.qty, remaining);
            if (taken > 0) {
                batch.qty -= taken;
                remaining -= taken;
                items.push({ batchId: batch.batchId, qty: taken });
                deducted.push({ batch, qty: taken });
            }
        }

        if (remaining > 0) {
            for (const { batch, qty } of deducted) {
                batch.qty += qty;
            }
            const result = { success: false, reason: 'insufficient_stock', available: totalAvailable };
            this.picks[pickId] = result;
            return result;
        }

        const result = { success: true, items };
        this.picks[pickId] = result;
        return result;
    }

