class Auction {
    constructor(startingPrice, minIncrement, endTime, extensionWindow = 0) {
        this.currentPrice = startingPrice;
        this.minIncrement = minIncrement;
        this.endTime = endTime;
        this.extensionWindow = extensionWindow; // extend deadline if bid within this window
        this.highBidder = null;
        this.highBidderMax = 0;    // proxy: max they're willing to pay
        this.bids = [];            // { bidder, amount, proxyMax, ts, resultPrice }
        this.closed = false;
