class GiftCardSystem {
    constructor(maxBalance = 500) {
        this.cards = {};  // cardId -> { balance, active, expiresAt, transactions }
        this.maxBalance = maxBalance;
    }

    issueCard(cardId, initialBalance, expiresAt) {
        this.cards[cardId] = {
            balance: Math.min(initialBalance, this.maxBalance),
            active: false,
            expiresAt,
            transactions: []
        };
    }

    _addTransaction(cardId, type, amount, balanceAfter, ts) {
        this.cards[cardId].transactions.push({ type, amount, balanceAfter, ts });
    }

golden_completion:
activate(cardId, ts) {
    const card = this.cards[cardId];
    if (!card) return { success: false, reason: 'not_found' };
    if (card.active) return { success: false, reason: 'already_active' };
    card.active = true;
    this._addTransaction(cardId, 'ACTIVATE', 0, card.balance, ts);
    return { success: true };
}

redeem(cardId, amount, ts) {
    const card = this.cards[cardId];
    if (!card) return { success: false, reason: 'not_found', charged: 0 };
    if (!card.active) return { success: false, reason: 'not_active', charged: 0 };
    if (ts > card.expiresAt) return { success: false, reason: 'expired', charged: 0 };
    const charged = Math.min(amount, card.balance);
    if (charged <= 0) return { success: false, reason: 'zero_balance', charged: 0 };
    card.balance -= charged;
    this._addTransaction(cardId, 'REDEEM', charged, card.balance, ts);
    return { success: true, charged, remaining: card.balance };
}

reload(cardId, amount, ts) {
    const card = this.cards[cardId];
    if (!card) return { success: false, reason: 'not_found' };
    if (!card.active) return { success: false, reason: 'not_active' };
    if (ts > card.expiresAt) return { success: false, reason: 'expired' };
    const accepted = Math.min(amount, this.maxBalance - card.balance);
    if (accepted <= 0) return { success: false, reason: 'at_cap' };
    card.balance += accepted;
    this._addTransaction(cardId, 'RELOAD', accepted, card.balance, ts);
    return { success: true, accepted, balance: card.balance };
}

