            candidates.push(preferredBinId);
        }
        for (const [binId, bin] of Object.entries(this.bins)) {
            if (binId !== preferredBinId && allowedZones.includes(bin.zone)) candidates.push(binId);
        }

        for (const binId of candidates) {
            const bin = this.bins[binId];
            if (bin.currentLoad + size <= bin.capacity) {
                bin.items.push({ itemId, zone, size });
                bin.currentLoad += size;
                this.log.push({ action: 'assign', itemId, binId });
                return binId;
            }
        }

        this.log.push({ action: 'assign', itemId, reason: 'no_space' });
        return null;
    }

