class LoyaltyProgram {
    constructor(tierMultipliers) {
        this.tierMultipliers = tierMultipliers; // { silver: 1, gold: 1.5, platinum: 2 }
        this.pointBatches = []; // { points, earnedAt, expiresAt }
        this.tier = 'silver';
        this.totalEarned = 0;
        this.totalBurned = 0;
        this.transactions = [];
    }

    get availablePoints() {
        return this.pointBatches.reduce((sum, b) => sum + b.points, 0);
    }

    earn(basePoints, currentDay) {
        const mult = this.tierMultipliers[this.tier] || 1;
        const actual = Math.floor(basePoints * mult);
        this.pointBatches.push({ points: actual, earnedAt: currentDay, expiresAt: currentDay + 365 });
        this.totalEarned += actual;
        this.transactions.push({ action: 'earn', base: basePoints, multiplier: mult, actual, day: currentDay });
        return actual;
    }

golden_completion:
burn(amount, currentDay) {
    this.pointBatches = this.pointBatches.filter(b => b.expiresAt > currentDay);
    let remaining = amount;
    const consumed = [];
    while (remaining > 0 && this.pointBatches.length > 0) {
        const batch = this.pointBatches[0];
        if (batch.points <= remaining) {
            remaining -= batch.points;
            consumed.push({ ...batch, used: batch.points });
            this.pointBatches.shift();
        } else {
            batch.points -= remaining;
            consumed.push({ earnedAt: batch.earnedAt, used: remaining });
            remaining = 0;
        }
    }
    const burned = amount - remaining;
    this.totalBurned += burned;
    this.transactions.push({ action: 'burn', requested: amount, burned, day: currentDay, batches: consumed.length });
    return burned;
}

suffix:
    upgradeTier(newTier) {
        if (this.tierMultipliers[newTier] === undefined) return false;
        const old = this.tier;
        this.tier = newTier;
        this.transactions.push({ action: 'upgrade', from: old, to: newTier });
        return true;
    }
}

