assignSeat(passengerId, seatId, needsAccessible) {
    const seat = this.seats[seatId];
    if (!seat || seat.occupied) {
        this.manifest.push({ passengerId, seatId, status: 'denied', reason: seat ? 'occupied' : 'invalid' });
        return false;
    }
    if (needsAccessible && !seat.accessible) {
        this.manifest.push({ passengerId, seatId, status: 'denied', reason: 'not_accessible' });
        return false;
    }
    seat.occupied = true;
    seat.passenger = passengerId;
    this.manifest.push({ passengerId, seatId, status: 'assigned', class: seat.class });
    return true;
}

