class EnrollmentPeriod {
    constructor(courseId, capacity, openDate, closeDate) {
        this.courseId = courseId;
        this.capacity = capacity;
        this.openDate = openDate;     // timestamp ms
        this.closeDate = closeDate;   // timestamp ms
        this.enrolled = [];           // { studentId, priority, enrolledAt }
        this.waitlist = [];           // { studentId, priority, waitlistedAt }
        this._studentIds = new Set(); // prevent double-enroll
    }

golden_completion:
enroll(studentId, priority, timestamp) {
    if (timestamp < this.openDate) return { status: 'not-open' };
    if (timestamp > this.closeDate) return { status: 'closed' };
    if (this._studentIds.has(studentId)) return { status: 'already-enrolled' };
    this._studentIds.add(studentId);
    if (this.enrolled.length < this.capacity) {
        this.enrolled.push({ studentId, priority, enrolledAt: timestamp });
        this.enrolled.sort((a, b) => a.priority - b.priority);
        return { status: 'enrolled', position: this.enrolled.findIndex(e => e.studentId === studentId) + 1 };
    }
    this.waitlist.push({ studentId, priority, waitlistedAt: timestamp });
    this.waitlist.sort((a, b) => a.priority - b.priority);
    return { status: 'waitlisted', position: this.waitlist.findIndex(e => e.studentId === studentId) + 1 };
}

