_getItemPrice(name, hour) {
    const item = this.items[name];
    if (!item) throw new Error(`Unknown item: ${name}`);
    return this._isHappyHour(hour) ? item.happyHourPrice : item.basePrice;
}

_round2(value) {
    return Math.round((value + Number.EPSILON) * 100) / 100;
}

order(itemNames, hour, timestamp) {
    let total = 0;
    let ingredientCost = 0;

    for (const name of itemNames) {
        total += this._getItemPrice(name, hour);
        const item = this.items[name];
        for (const ingredient of item.ingredients) {
            ingredientCost += (this.ingredientCosts[ingredient] || 0);
        }
    }

    const orderedSorted = [...itemNames].sort().join('|');
    for (const comboName in this.combos) {
        const combo = this.combos[comboName];
        if (combo.items.length === itemNames.length && [...combo.items].sort().join('|') === orderedSorted) {
            total *= (1 - combo.discount);
            break;
        }
    }

    total = this._round2(total);
    ingredientCost = this._round2(ingredientCost);
    const margin = this._round2(total - ingredientCost);

    const order = { items: [...itemNames], total, ingredientCost, margin, timestamp };
    this.orders.push(order);
    return order;
}

